def step(title,text,formula,start,end,begin):
 assert s.count(start,begin)==1,start;a=s.index(start,begin);b=s.index(end,a);code=s[a:b].rstrip()+'\n'
 return dict(title=title,text=text,formula=formula,lean=code,detail='Exact contiguous compiled BODY; the literal local definitions and preceding facts remain in scope. The first three blocks are the internal primitive helper, then the public first-clock proof.',lean_source_region=dict(path=file,source_raw_sha256=sha(Path(file).read_bytes()),start_line=s[:a].count('\n')+1,end_line=s[:a+len(code)].count('\n'),exact_code_raw_sha256=sha(code.encode())))
steps=[
 step('Reuse the actual flow, rate and conserved-energy bound','Take joint flow continuity and exact H conservation from the compiled harmonic-flow theorem, and rate continuity/nonnegativity and the same-energy-layer bound from the compiled bounce/rate theorem. Substitute Φ_s(z) into that bound and use H(Φ_s(z))=H(z). Positivity of the displayed factors proves C(z)≥0.',r'\lambda(x_{\rm ref},\Phi_s z)\ge0,\quad H(\Phi_s z)=H(z),\quad\lambda(x_{\rm ref},\Phi_s z)\le C(z),\quad C(z)\ge0.','  have hf :=','  have hF :',primitive_body),
 step('Construct the continuous cumulative hazard','The actual joint orbit rate is continuous. The parameter-dependent primitive theorem with real Lebesgue measure gives joint continuity of its integral up to t; restricting the endpoint to NNReal preserves continuity and Borel measurability. For each fixed phase, direct trigonometric continuity of Φ and continuity of λ prove interval integrability on every finite real interval.',r'(y,x_{\rm ref},z,t)\longmapsto\Lambda_z(t)\text{ is continuous and Borel},\qquad\lambda(x_{\rm ref},\Phi_\cdot z)\in L^1([0,t]).','  have hF :','  have hbasic (',primitive_body),
 step('Derive monotonicity and the integrated cap','The empty interval gives Λ(0)=0. Nonnegativity of the actual integrand gives Λ(t)≥0. Integral monotonicity on nested nonnegative intervals gives Λ(s)≤Λ(t) when s≤t. Integrating the same actual pointwise bound C(z) gives Λ(t)≤C(z)t. Collect these facts in the private helper; no integral or cap certificate becomes a public caller.',r'\Lambda_z(0)=0,\quad0\le\Lambda_z(s)\le\Lambda_z(t)\le C(z)t\quad(0\le s\le t).','  have hbasic (','\nset_option maxHeartbeats 1200000 in',primitive_body),
 step('Identify the exact finite-time crossing event','Reuse the proved primitive facts with their folded local types. The set A_e={s≥0:e≤Λ(s)} is closed by continuity. If A_e is nonempty, its infimum belongs to A_e because it is bounded below; monotonicity gives inf A_e≤t iff e≤Λ(t). If it is empty, τ=∞ and both sides are false. This is a closed-set argument on continuous NNReal time.',r'\tau_z(e)\le t\iff e\le\Lambda_z(t),\qquad\tau_z(e)=\infty\iff\forall t\ge0,\ \Lambda_z(t)<e.','  classical','  have hfinite (',body),
 step('Prove the first crossing has the exact threshold value','For finite τ=q, the crossing event gives e≤Λ(q). If Λ(q)>e, continuity on [0,q], Λ(0)=0 and e≥0 yield s≤q with Λ(s)=e by the intermediate value theorem. Strictness forces s<q, while the crossing equivalence forces q≤s, a contradiction. At time zero the same event proves e>0⇒τ>0 and τ(0)=0.',r'\tau_z(e)<\infty\Longrightarrow\Lambda_z(\tau_z(e))=e,\qquad e>0\Longrightarrow\tau_z(e)>0,\qquad\tau_z(0)=0.','  have hfinite (','  have hτmeas :',body),
 step('Prove the first clock is jointly Borel','The target extended time is generated by closed lower intervals. The preimage of Iic(∞) is the whole space. For finite t, the crossing event identifies the preimage as {e≤Λ_z(t)}, a Borel inequality between the threshold coordinate and the jointly Borel cumulative hazard. This proves joint measurability, including infinite waiting.',r'\{(y,x_{\rm ref},z,e):\tau_z(e)\le t\}=\{(y,x_{\rm ref},z,e):e\le\Lambda_z(t)\}\text{ is Borel}.','  have hτmeas :','  have hlaw (',body),
 step('Push forward the actual unit exponential law','The unit-rate exponential measure is a probability measure. Its map e↦τ_z(toNNReal e) is measurable by composing the jointly Borel clock with fixed parameters and the measurable nonnegative-part map. Hence its pushforward W_z is a probability measure. The finite-time event and Λ_z(t)≥0 identify the strict survival preimage exactly with {e>Λ_z(t)} on ℝ.',r'W_z\text{ is a probability measure},\qquad\{e:t<\tau_z(\max\{e,0\})\}=\{e:\Lambda_z(t)<e\}.','  have hlaw (','    change ((ProbabilityTheory.expMeasure',body),
 step('Evaluate the strict survival probability','Apply the measurable pushforward formula to Ioi(t). The preimage from the preceding block is Ioi(Λ_z(t)). Take the complement of Iic and use the exact Exp(1) CDF, 1−exp(−u) for u≥0, obtaining exp(−Λ_z(t)). Possible mass at infinite waiting is retained by the interval (t,∞].',r'W_z((t,\infty])=\Pr\{E>\Lambda_z(t)\}=1-(1-e^{-\Lambda_z(t)})=e^{-\Lambda_z(t)}.','    change ((ProbabilityTheory.expMeasure','  have hwait (',body),
 step('Extract the extended waiting lower bound and zero-cap branch','If C(z)>0 and τ is finite, the exact threshold identity and integrated cap give e=Λ_z(τ)≤C(z)τ, so e/C(z)≤τ. If τ=∞ the extended inequality is automatic. If C(z)=0 and e>0, every Λ_z(t)≤0<e; the no-hit equivalence gives τ=∞. Collect all ten conclusion groups, preserving the finite-hit guards.',r'C(z)>0\Longrightarrow\tau_z(e)\ge e/C(z),\qquad C(z)=0,\ e>0\Longrightarrow\tau_z(e)=\infty.','  have hwait (','\nend\n',body)
]
